def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Track opponent's moves
    opp_moves = [h[1] for h in history]
    my_moves = [h[0] for h in history]
    opp_coops = opp_moves.count('C')
    my_coops = my_moves.count('C')
    opp_coop_rate = opp_coops / n

    last_me = my_moves[-1]
    last_opp = opp_moves[-1]

    # Count opponent's consecutive defections at the end
    tail_def = 0
    for x in reversed(opp_moves):
        if x == 'D':
            tail_def += 1
        else:
            break

    # Count consecutive mutual cooperation at the end
    tail_cc = 0
    for h in reversed(history):
        if h[0] == 'C' and h[1] == 'C':
            tail_cc += 1
        else:
            break

    # Recent window analysis
    w = min(10, n)
    recent_opp = opp_moves[-w:]
    recent_coop = recent_opp.count('C')
    recent_rate = recent_coop / w

    remaining = 100 - n

    # Opponent persistently defecting: minimize losses
    if opp_coop_rate < 0.15 and n >= 8:
        # Rare reconciliation probe
        if tail_def >= 5 and rng.random() < 0.05:
            return 'C'
        return 'D'

    # Extremely cooperative opponent: exploit late, cooperate otherwise
    if opp_coop_rate > 0.9 and n >= 10:
        if remaining <= 3:
            return 'D'
        if tail_cc >= 6 and rng.random() < 0.06:
            return 'D'
        return 'C'

    # Very cooperative opponent overall
    if opp_coop_rate > 0.75:
        if last_opp == 'C':
            # Mostly cooperate, occasional light probe when mutual streak is long
            if tail_cc >= 8 and rng.random() < 0.08:
                return 'D'
            return 'C'
        # Opponent just defected
        if tail_def == 1:
            # Forgive isolated defection quickly
            return 'C'
        if tail_def == 2:
            # Punish lightly but signal willingness to return
            return 'D'
        return 'D'

    # Moderately cooperative opponent
    if opp_coop_rate > 0.45:
        if last_opp == 'C':
            if last_me == 'D':
                return 'C'
            # Small probe to test if exploitable, kept rare
            if tail_cc >= 5 and rng.random() < 0.05:
                return 'D'
            return 'C'
        # Opponent defected
        if tail_def == 1:
            # Sometimes retaliate, sometimes forgive to restore cooperation
            if recent_rate > 0.6 and rng.random() < 0.55:
                return 'C'
            return 'D'
        if tail_def == 2:
            return 'D'
        return 'D'

    # Low-cooperation opponent (rate < 0.45 but >= 0.15)
    if last_opp == 'C':
        # Reciprocate cooperation to encourage recovery
        if last_me == 'D' and rng.random() < 0.8:
            return 'C'
        if rng.random() < 0.1:
            return 'D'
        return 'C'
    else:
        # Opponent defected
        if tail_def >= 3:
            return 'D'
        if recent_rate < 0.2:
            return 'D'
        # Occasional conciliatory move to break retaliation cycles
        if tail_def == 1 and rng.random() < 0.2:
            return 'C'
        return 'D'
